"""Pure CODEOWNERS rendering and drift checks: values in, text out, no I/O."""

from __future__ import annotations

import difflib
from dataclasses import dataclass
from typing import Iterable, Sequence

from .models import ENVIRONMENTS, OwnersConfig

HEADER = """\
# GENERATED by `python -m tools.codeowners` from .github/teams.yaml. Do not edit by hand:
# change teams.yaml and re-run the tool. CI runs it with --check and fails on drift.
# Later rules override earlier ones; the last matching pattern wins.
"""


@dataclass(frozen=True)
class Rule:
    """One CODEOWNERS line."""

    pattern: str
    owners: tuple[str, ...]

    def line(self, width: int) -> str:
        return f"{self.pattern.ljust(width)} {' '.join(self.owners)}".rstrip()


def platform_rules(cfg: OwnersConfig) -> list[Rule]:
    """Platform-owned paths, in teams.yaml order. Pure."""
    return [Rule(p, cfg.platform_owners) for p in cfg.platform_paths]


def team_rules(cfg: OwnersConfig) -> list[Rule]:
    """One rule per team and environment, sorted by team. They come after the platform
    rules, so a team's rule wins over /environments/ for its own directories. Pure."""
    return [
        Rule(f"/environments/{env}/{team.slug}/", team.owners_for(env, cfg.org))
        for team in sorted(cfg.teams, key=lambda t: t.slug)
        for env in ENVIRONMENTS
    ]


def render(cfg: OwnersConfig) -> str:
    """The full CODEOWNERS file. Deterministic for a given config. Pure."""
    default = Rule("*", cfg.default_owners)
    platform, teams = platform_rules(cfg), team_rules(cfg)
    width = max(len(r.pattern) for r in [default, *platform, *teams])

    def block(comment: str, rs: list[Rule]) -> str:
        return comment + "".join(r.line(width) + "\n" for r in rs)

    sections = [
        HEADER,
        block("", [default]),
        block("# Platform-owned paths: policy gates, CI, modules and the stack tree fallback.\n", platform),
    ]
    if teams:
        sections.append(block("# Team stack roots: environments/<env>/<team>/.\n", teams))
    return "\n".join(sections)


def undeclared_teams(cfg: OwnersConfig, stack_teams: Iterable[str]) -> list[str]:
    """Teams that own stacks under environments/ but have no teams.yaml entry. Pure."""
    declared = {t.slug for t in cfg.teams}
    return sorted(set(stack_teams) - declared)


def drift(expected: str, actual: str | None, path: str) -> Sequence[str]:
    """A unified diff from the committed file to the generated one ([] when equal). Pure."""
    if actual == expected:
        return []
    return list(
        difflib.unified_diff(
            (actual or "").splitlines(keepends=True),
            expected.splitlines(keepends=True),
            fromfile=f"{path} (committed)",
            tofile=f"{path} (generated)",
        )
    )
